window.__AETHERLAN_HTML_PARTS=window.__AETHERLAN_HTML_PARTS||[];window.__AETHERLAN_HTML_PARTS.push("<!doctype html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"utf-8\" />\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\" />\n<title>艾瑟兰｜REV20.7 网页交互式人生游戏</title>\n<style>\n:root{--bg:#090a0d;--panel:#12151b;--panel2:#171b23;--gold:#d6b56f;--gold2:#8c6b33;--text:#eee8dc;--muted:#9da5b2;--line:#2b303a;--good:#7fbf91;--warn:#d8a35c;--bad:#c87676;--shadow:0 18px 70px rgba(0,0,0,.35)}\n*{box-sizing:border-box}html,body{margin:0;background:radial-gradient(circle at 20% -10%,#2a2318 0,#0d0f13 35%,#08090c 80%);color:var(--text);font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",\"PingFang SC\",\"Microsoft YaHei\",sans-serif;min-height:100%}button,input,select{font:inherit}\nbody:before{content:\"\";position:fixed;inset:0;pointer-events:none;background:linear-gradient(120deg,transparent 0 45%,rgba(214,181,111,.035) 50%,transparent 55%);background-size:440px 440px}\n.app{max-width:1420px;margin:auto;padding:18px}.top{display:flex;gap:14px;align-items:center;justify-content:space-between;margin-bottom:14px}.brand{display:flex;gap:12px;align-items:center}.sigil{width:44px;height:44px;border:1px solid var(--gold2);border-radius:50%;display:grid;place-items:center;color:var(--gold);box-shadow:inset 0 0 24px rgba(214,181,111,.08)}.brand h1{font-size:20px;margin:0}.brand small{color:var(--muted)}\n.pill{border:1px solid var(--line);background:#0f1217;border-radius:999px;padding:7px 11px;color:var(--muted);font-size:12px}.pill b{color:var(--gold)}\n.grid{display:grid;grid-template-columns:290px 1fr 310px;gap:14px}.panel{background:linear-gradient(180deg,rgba(22,25,32,.96),rgba(14,17,22,.96));border:1px solid var(--line);border-radius:16px;box-shadow:var(--shadow)}.pad{padding:16px}\n.step{display:flex;gap:10px;padding:11px;border-radius:12px;margin:5px 0;cursor:pointer;color:var(--muted);border:1px solid transparent}.step.active{background:rgba(214,181,111,.09);color:var(--text);border-color:#4c4028}.step.done .num{background:var(--gold);color:#16130d}.num{width:27px;height:27px;border:1px solid #4a4f5b;border-radius:50%;display:grid;place-items:center;font-size:12px;flex:none}.step strong{display:block;font-size:13px}.step span{font-size:11px}.content{min-height:670px;padding:20px}.content h2{margin:0 0 6px;font-size:24px}.sub{color:var(--muted);font-size:13px;margin-bottom:18px}.row{display:flex;gap:10px;flex-wrap:wrap}.field{margin:12px 0}.field label{font-size:12px;color:var(--muted);display:block;margin-bottom:7px}.input,select{width:100%;background:#0c0f14;color:var(--text);border:1px solid var(--line);border-radius:10px;padding:11px 12px;outline:none}.input:focus,select:focus{border-color:var(--gold2)}\n.btn{border:1px solid #5a4826;background:linear-gradient(180deg,#d5b46f,#ad8643);color:#17130d;font-weight:700;border-radius:10px;padding:10px 14px;cursor:pointer}.btn.secondary{background:#151921;color:var(--text);border-color:var(--line)}.btn.ghost{background:transparent;color:var(--gold);border-color:#4b4029}.btn:disabled{opacity:.4;cursor:not-allowed}.nav{display:flex;justify-content:space-between;margin-top:18px;padding-top:16px;border-top:1px solid var(--line)}\n.avatarWrap{display:grid;place-items:center;padding:14px;background:#0c0f14;border:1px solid var(--line);border-radius:14px}.avatar{width:190px;height:250px}.cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.card{border:1px solid var(--line);background:#0e1117;border-radius:13px;padding:13px;cursor:pointer;transition:.18s}.card:hover{border-color:#645333;transform:translateY(-1px)}.card.sel{border-color:var(--gold);box-shadow:0 0 0 1px rgba(214,181,111,.25) inset;background:#15150f}.card h3{font-size:14px;margin:0 0 5px}.card p{font-size:12px;color:var(--muted);line-height:1.6;margin:0}.tag{font-size:10px;color:var(--gold);border:1px solid #57472b;padding:3px 6px;border-radius:999px;display:inline-block;margin-right:5px;margin-top:5px}.muted{color:var(--muted)}\n.hubList{max-height:420px;overflow:auto;display:grid;gap:8px;margin-top:10px}.hub{padding:10px;border:1px solid var(--line);border-radius:10px;cursor:pointer;background:#0c0f14}.hub.sel{border-color:var(--gold);background:#15150f}.hub .name{font-weight:700;font-size:13px}.hub .meta{font-size:11px;color:var(--muted);margin-top:4px}.route{min-height:190px}.route .code{font-size:22px;color:var(--gold);font-weight:800}.route p{max-height:110px;overflow:auto}.mini{font-size:11px;color:var(--muted)}\n.summary dl{margin:0}.summary dt{font-size:10px;color:var(--muted);margin-top:12px;text-transform:uppercase;letter-spacing:.06em}.summary dd{margin:4px 0 0;font-size:13px}.bar{height:6px;background:#0a0c10;border-radius:99px;overflow:hidden;margin-top:5px}.bar i{display:block;height:100%;background:linear-gradient(90deg,#7f6739,#d6b56f)}\n.notice{border-left:3px solid var(--gold2);background:rgba(214,181,111,.06);padding:11px 12px;border-radius:8px;font-size:12px;line-height:1.6;color:#d9d4ca}.danger{border-left-color:var(--bad);background:rgba(200,118,118,.07)}\n.hidden{display:none!important}.game{display:none}.game.active{display:block}.creator.hidden{display:none}.gameTop{display:grid;grid-template-columns:1fr auto;gap:12px;align-items:center}.statbar{display:flex;gap:8px;flex-wrap:wrap}.stat{background:#0c0f14;border:1px solid var(--line);border-radius:10px;padding:7px 10px;font-size:11px;color:var(--muted)}.stat b{color:var(--text)}\n.gamegrid{display:grid;grid-template-columns:1fr 340px;gap:14px;margin-top:14px}.event{padding:18px}.event h2{margin:0 0 6px}.event .fact{font-size:14px;line-height:1.75;color:#ddd6c9}.event .chain{font-size:12px;line-height:1.7;color:var(--muted);border-top:1px solid var(--line);margin-top:13px;padding-top:12px}.choices{display:grid;grid-template-columns:repeat(2,1fr);gap:9px;margin-top:15px}.choice{background:#10141b;border:1px solid var(--line);border-radius:12px;padding:12px;cursor:pointer;text-align:left;color:var(--text)}.choice:hover{border-color:var(--gold2)}.choice b{display:block;color:var(--gold);margin-bottom:4px}.choice span{font-size:11px;color:var(--muted)}\n.log{max-height:500px;overflow:auto}.logitem{border-bottom:1px solid var(--line);padding:10px 0;font-size:12px;line-height:1.55}.logitem time{color:var(--gold);font-size:10px}.worldPulse{display:grid;grid-template-columns:repeat(3,1fr);gap:7px}.pulse{padding:9px;border:1px solid var(--line);border-radius:10px;text-align:center}.pulse b{font-size:17px;display:block}.pulse span{font-size:10px;color:var(--muted)}\n.timeline{border-left:1px solid #383c45;margin-left:5px;padding-left:13px}.stage{margin:10px 0}.stage b{font-size:12px;color:var(--gold)}.stage p{font-size:11px;color:var(--muted);margin:4px 0;line-height:1.6}\n@media(max-width:980px){.faceGrid{grid-template-columns:1fr!important}.grid{grid-template-columns:1fr}.sidebar{display:none}.content{min-height:auto}.summaryPanel{order:3}.gamegrid{grid-template-columns:1fr}.cards{grid-template-columns:1fr}.choices{grid-template-columns:1fr}.app{padding:10px}.top{align-items:flex-start}.brand h1{font-size:17px}}\n\n.worldLayer{margin-top:12px;border-top:1px solid var(--line);padding-top:12px}.worldLayer h4{margin:10px 0 7px;font-size:12px;color:var(--gold)}\n.worldmini{font-size:11px;line-height:1.55;color:var(--muted);max-height:180px;overflow:auto}.worldmini .wrow{padding:7px 0;border-bottom:1px solid var(--line)}\n.sagaBadge{display:inline-block;font-size:10px;border:1px solid #57472b;color:var(--gold);border-radius:999px;padding:2px 6px;margin:2px 3px 2px 0}\n.ledgerTabs{display:flex;gap:6px;flex-wrap:wrap;margin-top:8px}.ledgerTabs button{font-size:10px;padding:5px 8px}\n.eventKind{font-size:10px;letter-spacing:.08em;color:#d6b56f;border:1px solid #57472b;padding:3px 7px;border-radius:999px}\n.frontGrid{display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-top:8px}.front{border:1px solid var(--line);border-radius:9px;padding:7px;font-size:10px;color:var(--muted)}.front.here{border-color:var(--gold2);color:var(--text)}\n@media(max-width:980px){.frontGrid{grid-template-columns:1fr}}\n</style>\n</head>\n<body><div id=\"runtimeProbe\" style=\"max-width:1420px;margin:10px auto 0;padding:10px 14px;border:1px solid #5a4826;border-radius:12px;background:#17140e;color:#d6b56f;font:12px/1.6 -apple-system,BlinkMacSystemFont,\"Segoe UI\",\"PingFang SC\",sans-serif\">运行环境检测中……如果打开后一直停留在这句话，说明当前文件预览器没有执行 JavaScript；请把 HTML 保存后用支持脚本的浏览器打开。</div><noscript><div style=\"max-width:1420px;margin:10px auto;padding:12px;border:1px solid #c87676;border-radius:12px;background:#241516;color:#f0cccc\">当前环境已禁用 JavaScript，本游戏无法在此预览器中交互。请在 Safari / Chrome / Edge 等浏览器环境运行。</div></noscript>\n<div class=\"app\">\n  <div class=\"top\">\n    <div class=\"brand\"><div class=\"sigil\">Æ</div><div><h1>艾瑟兰 · REV20.7</h1><small>网页交互式人生游戏｜数据库驱动开局</small></div></div>\n    <div class=\"row\"><div class=\"pill\">固定数据：<b id=\"dataCount\">1270 HUB · 5080 前传 · 7724 THREAD</b></div><div class=\"pill\" id=\"loadState\">界面：<b style=\"color:var(--good)\">已就绪</b></div></div>\n  </div>\n\n  <section class=\"creator\" id=\"creator\">\n  <div class=\"grid\">\n    <aside class=\"panel pad sidebar\">\n      <div class=\"step active\" data-step=\"0\"><div class=\"num\">1</div><div><strong>人物捏脸</strong><span>PC 固定人族男性，外貌自由</span></div></div>\n      <div class=\"step\" data-step=\"1\"><div class=\"num\">2</div><div><strong>出生地点</strong><span>1270 个固定 HUB</span></div></div>\n      <div class=\"step\" data-step=\"2\"><div class=\"num\">3</div><div><strong>成长路线</strong><span>每地 4 条合法前传</span></div></div>\n      <div class=\"step\" data-step=\"3\"><div class=\"num\">4</div><div><strong>职业与道路</strong><span>生活职业 ≠ 超凡职业</span></div></div>\n      <div class=\"step\" data-step=\"4\"><div class=\"num\">5</div><div><strong>确认开局</strong><span>18 岁进入动态世界</span></div></div>\n      <div class=\"notice\" style=\"margin-top:14px\">世界硬锁：PC-001 固定为人族男性；0—17 岁只运行身份、教育、迁徙、资产、文书与基础超凡训练。成年剧情从生命第 <b>6570</b> 日起开放。</div>\n    </aside>\n\n    <main class=\"panel content\">\n      <div class=\"page\" data-page=\"0\">\n        <h2>塑造你的成年面貌</h2><div class=\"sub\">这些选项只改变 PC-001 的可见外貌与自我称呼，不改写 ROOT-RACE、性别与父型权柄硬锁。</div>\n        <div style=\"display:grid;grid-template-columns:240px 1fr;gap:18px\" class=\"faceGrid\">\n          <div><div class=\"avatarWrap\"><svg id=\"avatar\" class=\"avatar\" viewBox=\"0 0 200 260\"><defs><linearGradient id=\"g0\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\"><stop stop-color=\"#333844\"/><stop offset=\"1\" stop-color=\"#11151c\"/></linearGradient><radialGradient id=\"skin0\" cx=\"45%\" cy=\"35%\" r=\"70%\"><stop stop-color=\"#e5b894\"/><stop offset=\"1\" stop-color=\"#bd8666\"/></radialGradient></defs><rect width=\"200\" height=\"260\" rx=\"18\" fill=\"url(#g0)\"/><circle cx=\"100\" cy=\"108\" r=\"45\" fill=\"url(#skin0)\"/><rect x=\"88\" y=\"151\" width=\"24\" height=\"42\" rx=\"11\" fill=\"#d7a27c\"/><path d=\"M60 86 Q59 39 100 31 Q143 38 141 85 Q123 61 100 62 Q76 62 60 86Z\" fill=\"#181510\"/><path d=\"M48 246 Q60 188 100 184 Q140 188 152 246 L161 260 H39Z\" fill=\"#26313e\"/><ellipse cx=\"84\" cy=\"108\" rx=\"5.8\" ry=\"3.4\" fill=\"#4b382d\"/><ellipse cx=\"116\" cy=\"108\" rx=\"5.8\" ry=\"3.4\" fill=\"#4b382d\"/><path d=\"M77 97 Q84 92 91 97 M109 97 Q116 92 123 97\" stroke=\"#584435\" stroke-width=\"2.3\" fill=\"none\" stroke-linecap=\"round\"/><path d=\"M100 111 Q96 126 102 130\" stroke=\"#9b6f57\" stroke-width=\"1.6\" fill=\"none\"/><path d=\"M89 145 Q100 150 111 145\" stroke=\"#8d5f55\" stroke-width=\"2\" fill=\"none\" stroke-linecap=\"round\"/><text x=\"100\" y=\"233\" text-anchor=\"middle\" fill=\"#d6b56f\" font-size=\"11\">PC-001 · HUMAN · MALE</text><text x=\"100\" y=\"249\" text-anchor=\"middle\" fill=\"#9da5b2\" font-size=\"9\">实时外貌预览</text></svg><div class=\"mini\" id=\"faceStatus\" style=\"text-align:center;margin-top:7px\">人物预览已就绪</div></div><button class=\"btn secondary\" style=\"width:100%;margin-top:9px\" id=\"randomFace\">随机外貌</button></div>\n          <div>\n            <div class=\"field\"><label>姓名</label><input class=\"input\" id=\"name\" value=\"张三\" maxlength=\"16\"></div>\n            <div class=\"row\"><div class=\"field\" style=\"flex:1\"><label>成年身高</label><input class=\"input\" id=\"height\" type=\"range\" min=\"155\" max=\"195\" value=\"176\"><div class=\"mini\"><span id=\"heightVal\">176</span> cm</div></div><div class=\"field\" style=\"flex:1\"><label>体型</label><select id=\"build\"><option>纤细</option><option selected>匀称</option><option>结实</option><option>修长</option></select></div></div>\n            <div class=\"row\"><div class=\"field\" style=\"flex:1\"><label>肤色</label><select id=\"skin\"><option value=\"#f0c7a5\">浅暖</option><option value=\"#d7a27c\" selected>自然暖</option><option value=\"#b97a55\">小麦</option><option value=\"#8e5d43\">深暖</option></select></div><div class=\"field\" style=\"flex:1\"><label>脸型</label><select id=\"face\"><option>柔和椭圆</option><option>偏窄</option><option>圆润</option><option>利落</option></select></div></div>\n            <div class=\"row\"><div class=\"field\" style=\"flex:1\"><label>发色</label><select id=\"hair\"><option value=\"#181510\">黑褐</option><option value=\"#34251b\">深棕</option><option value=\"#76654d\">灰棕</option><option value=\"#c6b997\">浅灰金</option></select></div><div class=\"field\" style=\"flex:1\"><label>发型</label><select id=\"hairStyle\"><option>短碎发</option><option>中长层次</option><option>束发</option><option>齐肩</option></select></div></div>\n            <div class=\"row\"><div class=\"field\" style=\"flex:1\"><label>瞳色</label><select id=\"eye\"><option value=\"#4b382d\">深棕</option><option value=\"#68788c\">灰蓝</option><option value=\"#61765c\">灰绿</option><option value=\"#92734d\">琥珀</option></select></div><div class=\"field\" style=\"flex:1\"><label>气质</label><select id=\"vibe\"><option>安静克制</option><option>温和</option><option>冷静</option><option>锋利</option><option>书卷气</option></select></div></div>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"page hidden\" data-page=\"1\">\n        <h2>选择出生地点</h2><div class=\"sub\">搜索任意国家、城市、城区、家系、封地、荒野、海域、神国或深渊 HUB。每个地点继承自己的文化锚点、人物、组织和剧情线程。</div>\n        <div class=\"row\"><input id=\"hubSearch\" class=\"input\" style=\"flex:1\" placeholder=\"输入：白塔、洛瑟兰、海镜、深渊……\"><select id=\"hubType\" style=\"width:180px\"><option value=\"\">全部类型</option></select></div>\n        <div class=\"hubList\" id=\"hubList\"></div><div class=\"mini\" id=\"hubResultCount\"></div>\n      </div>\n\n      <div class=\"page hidden\" data-page=\"2\">\n        <h2>选择 0—17 岁成长路线</h2><div class=\"sub\" id=\"routeSubtitle\"></div>\n        <div class=\"cards\" id=\"routeCards\"></div>\n        <div class=\"timeline\" id=\"routeTimeline\" style=\"margin-top:14px\"></div>\n      </div>\n\n      <div class=\"page hidden\" data-page=\"3\">\n        <h2>职业与力量道路</h2><div class=\"sub\">社会身份决定你靠什么参与社会；超凡职业决定你如何使用力量。18 岁开局不会因选择职业而凭空获得阶位。</div>\n        <div class=\"cards\">\n          <div class=\"card\" style=\"cursor:default\"><h3>社会 / 生活职业</h3><div class=\"field\"><label>职业</label><select id=\"socialJob\"></select></div><p id=\"jobFit\"></p></div>\n          <div class=\"card\" style=\"cursor:default\"><h3>超凡道路</h3><div class=\"field\"><label>力量来源</label><select id=\"powerPath\"><option value=\"NONE\">暂无正式超凡道路</option><option value=\"MARTIAL\">武道 / 肉身锻炼</option><option value=\"ARCANE\">奥术 / 魔法学习</option><option value=\"PACT\">神魔契约</option><option value=\"HYBRID\">混合道路</option></select></div><div class=\"field\"><label>目标职业传统</label><select id=\"powerJob\"></select></div><p>如果前传与当地资源不足以支撑正式资格，会以“学徒 / 见习 / 候选者”进入成年阶段。</p></div>\n        </div>\n        <div class=\"notice\" style=\"margin-top:12px\">PC-001 对武道、奥术、契约都有高适配，但真神以前仍必须训练、学习、建立能力链并逐阶晋升。网页只把它作为成长潜力，不直接赠送战力。</div>\n      </div>\n\n      <div class=\"page hidden\" data-page=\"4\">\n        <h2>确认开局</h2><div class=\"sub\">生成 18 岁成年快照，并从你出生 HUB 的真实 THREAD 池开始运行。</div>\n        <div id=\"finalReview\"></div>\n        <div class=\"notice\" style=\"margin-top:13px\">本网页的数值条（资金、关系、证据等）是为了交互化而建立的运行参数；它们不替代 REV20.7 的世界事实。地点、成长路线、THREAD 事实、核心人物和因果时钟均来自当前数据源。</div>\n      </div>\n\n      <div class=\"nav\"><button class=\"btn secondary\" id=\"prev\">上一步</button><button class=\"btn\" id=\"next\">下一步</button></div>\n    </main>\n\n    <aside class=\"panel pad summaryPanel\"><div class=\"summary\" id=\"summary\"></div></aside>\n  </div>\n  </section>\n\n  <section class=\"game\" id=\"game\">\n    <div class=\"panel pad gameTop\"><div><h2 style=\"margin:0\">成年世界已启动</h2><div class=\"mini\" id=\"gameIdentity\"></div></div><div class=\"row\"><button class=\"btn secondary\" id=\"saveBtn\">导出存档</button><label class=\"btn secondary\" style=\"cursor:pointer\">导入存档<input id=\"loadInput\" type=\"file\" accept=\"application/json\" hidden></label><button class=\"btn ghost\" id=\"newGame\">新开局</button></div></div>\n    <div class=\"statbar\" id=\"statbar\" style=\"margin-top:10px\"></div>\n    <div class=\"gamegrid\">\n      <main class=\"panel event\"><div id=\"eventArea\"></div></main>\n      <aside class=\"panel pad\"><h3 style=\"margin-top:0\">世界账本</h3><div class=\"worldPulse\" id=\"worldPulse\"></div><div class=\"row\" style=\"margin-top:10px\"><button class=\"btn secondary\" id=\"advance7\">推进 7 日</button><button class=\"btn secondary\" id=\"advance30\">推进 30 日</button></div><div class=\"worldLayer\" id=\"worldLayer\"></div><h3>近期记录</h3><div class=\"log\" id=\"log\"></div></aside>\n    </div>\n  </section>\n</div>\n\n<script>\n(()=>{\n  const $=s=>document.querySelector(s);\n  const setState=(t,good=false)=>{const e=$('#loadState'); if(e)e.innerHTML='世界数据：<b style=\"color:'+(good?'var(--good)':'var(--gold)')+'\">'+t+'</b>';};\n  window.__coreReady=false; window.__worldReady=false; const rp=$('#runtimeProbe'); if(rp)rp.innerHTML='运行环境：<b style=\"color:var(--good)\">JavaScript 已启动</b>｜正在加载游戏核心数据…';\n  window.addEventListener('error',e=>{const fs=$('#faceStatus');if(fs)fs.textContent='页面错误：'+(e.message||'未知错误');});\n  function bootDraw(){\n    const svg=$('#avatar'); if(!svg)return;\n    const skin=$('#skin')?.value||'#d7a27c',hair=$('#hair')?.value||'#181510',eye=$('#eye')?.value||'#4b382d',build=$('#build')?.value||'匀称',face=$('#face')?.value||'柔和椭圆',style=$('#hairStyle')?.value||'短碎发',vibe=$('#vibe')?.value||'安静克制';\n    const width={纤细:56,匀称:64,结实:72,修长:58}[build]||64, rx=face==='偏窄'?36:face==='圆润'?43:face==='利落'?38:40;\n    const hp=style==='齐肩'?`M55 93 Q52 40 100 31 Q148 40 145 93 L151 145 Q132 132 126 84 Q100 62 74 84 Q68 132 49 145Z`:style==='束发'?`M57 83 Q58 37 100 30 Q142 37 143 83 Q127 63 100 61 Q73 63 57 83 M142 58 Q173 71 151 105 Q160 73 138 70Z`:style==='中长层次'?`M55 92 Q53 39 100 30 Q147 39 145 92 L151 126 Q135 116 128 80 Q99 61 72 81 Q66 116 49 126Z`:`M58 82 Q58 39 100 32 Q142 39 142 82 Q124 64 100 63 Q76 64 58 82Z`;\n    svg.innerHTML=`<defs><linearGradient id=\"bgFace\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\"><stop stop-color=\"#343945\"/><stop offset=\"1\" stop-color=\"#10141b\"/></linearGradient><radialGradient id=\"skinShade\" cx=\"42%\" cy=\"32%\" r=\"72%\"><stop stop-color=\"${skin}\"/><stop offset=\"1\" stop-color=\"${skin}\" stop-opacity=\".82\"/></radialGradient></defs><rect width=\"200\" height=\"260\" rx=\"18\" fill=\"url(#bgFace)\"/><ellipse cx=\"100\" cy=\"250\" rx=\"${width}\" ry=\"58\" fill=\"#202936\"/><path d=\"M${100-width} 244 Q100 184 ${100+width} 244 L${100+width+9} 260 L${100-width-9} 260Z\" fill=\"#26313e\"/><rect x=\"88\" y=\"164\" width=\"24\" height=\"37\" rx=\"11\" fill=\"${skin}\"/><ellipse cx=\"100\" cy=\"111\" rx=\"${rx}\" ry=\"66\" fill=\"url(#skinShade)\"/><ellipse cx=\"61\" cy=\"112\" rx=\"7\" ry=\"13\" fill=\"${skin}\" opacity=\".92\"/><ellipse cx=\"139\" cy=\"112\" rx=\"7\" ry=\"13\" fill=\"${skin}\" opacity=\".92\"/><path d=\"${hp}\" fill=\"${hair}\"/><ellipse cx=\"84\" cy=\"108\" rx=\"5.5\" ry=\"3.2\" fill=\"${eye}\"/><ellipse cx=\"116\" cy=\"108\" rx=\"5.5\" ry=\"3.2\" fill=\"${eye}\"/><circle cx=\"84\" cy=\"108\" r=\"1.4\" fill=\"#111\"/><circle cx=\"116\" cy=\"108\" r=\"1.4\" fill=\"#111\"/><path d=\"M78 97 Q84 93 91 97 M109 97 Q116 93 123 97\" stroke=\"#554235\" stroke-width=\"2\" fill=\"none\" stroke-linecap=\"round\"/><path d=\"M100 112 Q96 128 102 130\" stroke=\"#9d6f55\" stroke-width=\"1.5\" fill=\"none\"/><path d=\"M89 145 Q100 ${vibe==='温和'?151:148} 111 145\" stroke=\"#8d5f55\" stroke-width=\"2\" fill=\"none\" stroke-linecap=\"round\"/><path d=\"M74 84 Q100 63 128 84\" stroke=\"rgba(255,255,255,.08)\" fill=\"none\"/><text x=\"100\" y=\"232\" text-anchor=\"middle\" fill=\"#d6b56f\" font-size=\"11\">PC-001 · HUMAN · MALE</text><text x=\"100\" y=\"248\" text-anchor=\"middle\" fill=\"#9da5b2\" font-size=\"9\">实时人物预览</text>`;\n  }\n  ['height','build','skin','face','hair','hairStyle','eye','vibe'].forEach(id=>$('#'+id)?.addEventListener('input',()=>{bootDraw(); if(id==='height'&&$('#heightVal'))$('#heightVal').textContent=$('#height').value;}));\n  $('#randomFace')?.addEventListener('click',()=>{if(window.__coreReady)return; const ids=['build','skin','face','hair','hairStyle','eye','vibe']; for(const id of ids){const el=$('#'+id);if(el&&el.options){el.selectedIndex=Math.floor(Math.random()*el.options.length)}} const h=$('#height');if(h){h.value=160+Math.floor(Math.random()*31);if($('#heightVal'))$('#heightVal').textContent=h.value;}bootDraw();});\n  // While databases load, every click still gives visible feedback instead of appearing dead.\n  document.addEventListener('click',e=>{const n=e.target.closest('#next,.step,.hub'); if(n&&!window.__coreReady){e.preventDefault();e.stopImmediatePropagation();setState('核心数据库加载中…');}},true);\n  document.addEventListener('click',e=>{const n=e.target.closest('#next');if(n&&window.__coreReady&&!window.__worldReady&&n.textContent.includes('进入艾瑟兰')){e.preventDefault();e.stopImmediatePropagation();setState('长期世界数据库加载中…');}},true);\n  bootDraw(); setState('界面已就绪，正在后台加载核心数据库',true);\n  window.__setLoadState=setState;\n})();\n</script>\n\n<script type=\"application/octet-stream\" id=\"dbPayload\">");